// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 < (1 << 255) - 1 && amount2 < (1 << 255) - 1);
        address sender1 = address(bytes20(keccak256(abi.encodePacked("s1", amount1))));
        address sender2 = address(bytes20(keccak256(abi.encodePacked("s2", amount2))));
        vm.assume(sender1 != sender2);

        vm.deal(sender1, amount1);
        vm.prank(sender1);
        c.addToBalance{value: amount1}();

        vm.deal(sender2, amount2);
        vm.prank(sender2);
        bool ok;
        try c.addToBalance{value: amount2}() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
